"use client";

import { useEffect, useState } from "react";
import { apiFetch } from "../../lib/api";

interface User {
  id: string;
  name: string;
  email: string;
  avatar?: string | null;
}

interface Email {
  id: string;
  recipient: string;
  subject: string;
  status: "SCHEDULED" | "PROCESSING" | "SENT" | "FAILED";
  scheduledAt: string;
  sentAt?: string | null;
}

interface MeResponse {
  user: User;
}

interface EmailsResponse {
  emails: Email[];
}

export default function DashboardPage() {
  const [user, setUser] = useState<User | null>(null);
  const [emails, setEmails] = useState<Email[]>([]);

  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    async function loadDashboard() {
      try {
        const [userData, emailData]: [
          MeResponse,
          EmailsResponse
        ] = await Promise.all([
          apiFetch("/auth/me"),
          apiFetch("/api/emails"),
        ]);

        setUser(userData.user);
        setEmails(emailData.emails);
      } catch (error) {
        console.error(error);
        setError("Unable to load dashboard.");
      } finally {
        setLoading(false);
      }
    }

    loadDashboard();
  }, []);

  const scheduledCount = emails.filter(
    (email) => email.status === "SCHEDULED"
  ).length;

  const sentCount = emails.filter(
    (email) => email.status === "SENT"
  ).length;

  const failedCount = emails.filter(
    (email) => email.status === "FAILED"
  ).length;

  if (loading) {
    return (
      <main className="flex min-h-screen items-center justify-center bg-slate-950 text-white">
        <div className="text-center">
          <div className="mx-auto mb-4 h-10 w-10 animate-spin rounded-full border-4 border-slate-700 border-t-white" />

          <p className="text-lg text-slate-300">
            Loading dashboard...
          </p>
        </div>
      </main>
    );
  }

  if (error || !user) {
    return (
      <main className="flex min-h-screen items-center justify-center bg-slate-950 px-6 text-white">
        <div className="w-full max-w-md rounded-2xl bg-white p-8 text-center text-slate-900 shadow-xl">
          <h1 className="mb-2 text-2xl font-bold">
            Authentication Required
          </h1>

          <p className="mb-6 text-slate-500">
            Please login with Google to access your dashboard.
          </p>

          <a
            href="http://localhost:5000/auth/google"
            className="inline-block rounded-lg bg-slate-900 px-6 py-3 font-medium text-white transition hover:bg-slate-800"
          >
            Continue with Google
          </a>
        </div>
      </main>
    );
  }

  return (
    <main className="min-h-screen bg-slate-950 text-white">
      <div className="mx-auto max-w-7xl px-6 py-8">

        {/* Header */}
        <header className="mb-8">
          <p className="mb-2 text-sm font-medium text-blue-400">
            REACHINBOX
          </p>

          <h1 className="text-3xl font-bold">
            Dashboard
          </h1>

          <p className="mt-2 text-slate-400">
            Manage your email campaigns
          </p>
        </header>

        {/* User Card */}
        <section className="rounded-2xl bg-white p-6 text-slate-900 shadow-xl">
          <div className="flex items-center gap-4">

            {user.avatar ? (
              <img
                src={user.avatar}
                alt={user.name}
                className="h-16 w-16 rounded-full object-cover"
              />
            ) : (
              <div className="flex h-16 w-16 items-center justify-center rounded-full bg-slate-900 text-xl font-bold text-white">
                {user.name.charAt(0).toUpperCase()}
              </div>
            )}

            <div>
              <p className="text-sm text-slate-500">
                Welcome back
              </p>

              <h2 className="text-xl font-semibold">
                {user.name}
              </h2>

              <p className="text-slate-500">
                {user.email}
              </p>
            </div>
          </div>
        </section>

        {/* Statistics */}
        <section className="mt-6 grid gap-6 md:grid-cols-3">

          {/* Scheduled */}
          <div className="rounded-2xl bg-white p-6 text-slate-900 shadow">
            <p className="text-sm font-medium text-slate-500">
              Scheduled
            </p>

            <p className="mt-2 text-4xl font-bold">
              {scheduledCount}
            </p>

            <p className="mt-2 text-sm text-slate-500">
              Emails waiting to be sent
            </p>
          </div>

          {/* Sent */}
          <div className="rounded-2xl bg-white p-6 text-slate-900 shadow">
            <p className="text-sm font-medium text-slate-500">
              Sent
            </p>

            <p className="mt-2 text-4xl font-bold">
              {sentCount}
            </p>

            <p className="mt-2 text-sm text-slate-500">
              Successfully delivered
            </p>
          </div>

          {/* Failed */}
          <div className="rounded-2xl bg-white p-6 text-slate-900 shadow">
            <p className="text-sm font-medium text-slate-500">
              Failed
            </p>

            <p className="mt-2 text-4xl font-bold">
              {failedCount}
            </p>

            <p className="mt-2 text-sm text-slate-500">
              Emails that failed
            </p>
          </div>

        </section>

        {/* Recent Emails */}
        <section className="mt-8 rounded-2xl bg-white p-6 text-slate-900 shadow-xl">

          <div className="mb-6">
            <h2 className="text-xl font-semibold">
              Recent Emails
            </h2>

            <p className="mt-1 text-sm text-slate-500">
              Your latest scheduled and sent emails
            </p>
          </div>

          {emails.length === 0 ? (
            <div className="rounded-xl border border-dashed border-slate-300 py-12 text-center">
              <p className="font-medium text-slate-700">
                No emails yet
              </p>

              <p className="mt-1 text-sm text-slate-500">
                Create your first email campaign to get started.
              </p>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-left">

                <thead>
                  <tr className="border-b border-slate-200 text-sm text-slate-500">
                    <th className="px-4 py-3">
                      Recipient
                    </th>

                    <th className="px-4 py-3">
                      Subject
                    </th>

                    <th className="px-4 py-3">
                      Status
                    </th>

                    <th className="px-4 py-3">
                      Scheduled
                    </th>
                  </tr>
                </thead>

                <tbody>
                  {emails.slice(0, 10).map((email) => (
                    <tr
                      key={email.id}
                      className="border-b border-slate-100 last:border-0"
                    >
                      <td className="px-4 py-4">
                        {email.recipient}
                      </td>

                      <td className="px-4 py-4">
                        {email.subject}
                      </td>

                      <td className="px-4 py-4">
                        <span
                          className={`rounded-full px-3 py-1 text-xs font-medium ${
                            email.status === "SENT"
                              ? "bg-green-100 text-green-700"
                              : email.status === "FAILED"
                              ? "bg-red-100 text-red-700"
                              : "bg-yellow-100 text-yellow-700"
                          }`}
                        >
                          {email.status}
                        </span>
                      </td>

                      <td className="px-4 py-4 text-sm text-slate-500">
                        {new Date(
                          email.scheduledAt
                        ).toLocaleString()}
                      </td>
                    </tr>
                  ))}
                </tbody>

              </table>
            </div>
          )}

        </section>

      </div>
    </main>
  );
}